#include <bit>
#include <iostream>
#include <vector>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n, m;
    std::cin >> n >> m;

    std::vector<unsigned> sets(m, 0);
    for (int i = 0; i < m; ++i) {
        int k;
        std::cin >> k;
        for (int j = 0; j < k; ++j) {
            int item;
            std::cin >> item;
            sets[i] |= 1u << item;
        }
    }

    const unsigned full = (1u << n) - 1;

    // Repeatedly take whichever set covers the most items not yet covered.
    unsigned covered = 0;
    int used = 0;
    while (covered != full) {
        int best_gain = 0;
        unsigned best_set = 0;
        for (unsigned s : sets) {
            int gain = std::popcount(s & ~covered & full);
            if (gain > best_gain) { best_gain = gain; best_set = s; }
        }
        if (best_gain == 0) { used = -1; break; }
        covered |= best_set;
        ++used;
    }

    std::cout << used << '\n';
}

