#include <deque>
#include <iostream>
#include <vector>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n, m;
    std::cin >> n >> m;

    std::vector<unsigned> sets(m, 0);
    for (int i = 0; i < m; ++i) {
        int k;
        std::cin >> k;
        for (int j = 0; j < k; ++j) {
            int item;
            std::cin >> item;
            sets[i] |= 1u << item;
        }
    }

    const unsigned full = (1u << n) - 1;

    // Shortest path over "which items are covered" states; every set costs 1.
    std::vector<int> dist(full + 1, -1);
    dist[0] = 0;
    std::deque<unsigned> queue{0u};

    while (!queue.empty()) {
        unsigned mask = queue.front();
        queue.pop_front();
        if (mask == full) break;
        for (unsigned s : sets) {
            unsigned next = mask | s;
            if (dist[next] == -1) {
                dist[next] = dist[mask] + 1;
                queue.push_back(next);
            }
        }
    }

    std::cout << dist[full] << '\n';
}
